library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use ieee.math_real.all;


entity uarttransmittest is 
    port(clk        :   in  std_logic;
         start_button    :   in  std_logic;
         serial_out : out std_logic);
end entity;

architecture rtl of uarttransmittest is

    component UART_transmit is
        port(
            clk                     :   in  std_logic;
            en_uart_transmit        :   in  std_logic;
            paralel_in              :   in  std_logic_vector(511 downto 0);
            serial_out              :   out std_logic;
            uart_transmitted_flag   :   out std_logic   
        );
    end component;
    signal en_uart_transmit :   std_logic;
    signal paralel_in       :   std_logic_vector(511 downto 0);
    signal uart_transmitted_flag : std_logic;

    type state is (start, checkdone, starting, done);
    signal currentstate : state := start;
begin
    uart_transmit_instantiation : uart_transmit port map(clk, en_uart_transmit, paralel_in, serial_out, uart_Transmitted_flag);
    mainfsm     :   process(clk, currentstate, start_button, uart_transmitted_flag)
    begin
        if (rising_edge(clk)) then
            case currentstate is
                when start =>
                    paralel_in <= "";
						  en_uart_transmit <= '0';
						  if(start_button = '0') then
								currentstate <= starting;
						  else
								currentstate <= start;
						  end if;
					 when starting =>
                    paralel_in <= "";
						  en_uart_transmit <= '1';
						  currentstate<= checkdone;
					 when checkdone =>
						  paralel_in <= "";
						  en_uart_transmit <= '0';
						  if (uart_transmitted_flag = '1') then
								currentstate <= done;
						  else
								currentstate <= checkdone;
						  end if;
                when done =>
                    paralel_in <= "";
                    en_uart_transmit <= '0';
						  if (start_button = '0') then
								currentstate <= start;
							else
								currentstate <= done;
							end if;
            end case;
        end if;
    end process;
end architecture;